insert into public.drills (id, status, content) values
  ('a-bugs-life', 'in_review', '{"funName":"A Bug’s Life","plainName":"Stickhandle the food to the ant hill","sourceTitle":"A Bug’s Life","minutes":10,"gear":"All the pucks, 1 net","worksAsStation":true,"description":"The pucks are food, piled in one corner, and the net is the ant hill. Skaters are ants: take a puck, stickhandle it to the ant hill and score. Coaches are grasshoppers who try to steal the food. Steal it back or grab another. Get all the food into the hill before winter (the whistle).","steps":["Take some food and stickhandle it to the ant hill.","Score it in the net.","A grasshopper stole it? Steal it back or grab another."],"cues":["Keep the food close!","Before winter comes!"],"focus":[{"attribute":"Puck control","level":2,"why":"Stickhandling past the grasshoppers."},{"attribute":"Effort & fun","level":2,"why":"Everyone races to beat the whistle."},{"attribute":"Shooting","level":1,"why":"Scoring into the ant hill."}],"groupModel":"basic","part":"game","effort":"hard","format":"everyone","lessons":[8,10,12],"levelName":"","levels":[],"source":{"label":"Hockey Canada U7 Lesson 8 · fun game (Phase II Lessons 10, 12, 16)","url":"https://cdn.hockeycanada.ca/hockey-canada/Hockey-Programs/Coaching/u7-program/downloads/2022/u7-practice-plans-phase-1-e.pdf","note":"Lesson 8 piles the food at centre with a net at each end. On half ice we use the Lesson 10 station version: food in one corner, the real net as the ant hill."},"diagram":{"scope":"half","side":"left","players":[{"x":62,"y":14,"role":"O"},{"x":30,"y":36,"role":"O"},{"x":48,"y":60,"role":"C"},{"x":30,"y":72,"role":"O"}],"paths":[{"type":"puck","points":[[62,14],[50,22],[38,32],[32,35]],"step":1,"caption":"Take some food and stickhandle it to the ant hill."},{"type":"shot","points":[[30,36],[14,41]],"step":2,"caption":"Score it in the net."},{"type":"skate","points":[[30,72],[40,68],[46,63]],"step":3,"caption":"A grasshopper stole it? Steal it back or grab another."}],"piles":[{"x":68,"y":8}],"labels":[{"x":8,"y":52,"text":"Ant hill"}],"pucks":[{"x":51,"y":58}],"cones":[]},"id":"a-bugs-life"}'::jsonb),
  ('airplanes', 'in_review', '{"funName":"Airplanes","plainName":"Glides, follow the leader","sourceTitle":"Follow the Leader: Glides","minutes":6,"gear":"None","worksAsStation":false,"description":"The coach leads a set of challenges across the ice. Pivot to face the other boards and back. Then glide across: on two skates, on one, with knees bent, with one leg stretched out. Finish with backward glides.","steps":["Pivot to face the other boards, then back.","Glide across: two skates, then one.","Backward glides on the way back."],"cues":["Proud chest, soft knees.","Hold it like a statue!"],"focus":[{"attribute":"Skating","level":2,"why":"Balance and glides on one skate."},{"attribute":"Effort & fun","level":1,"why":"“Bet you can’t do this one!”"}],"groupModel":"basic","part":"skill","effort":"medium","format":"everyone","lessons":[],"levelName":"Two-skate glides","levels":[{"name":"One-skate glides, both feet","adds":"One-skate glides, both feet.","diagram":{"scope":"half","side":"left","players":[{"x":30,"y":6,"role":"C"},{"x":20,"y":10,"role":"O"},{"x":36,"y":10,"role":"O"},{"x":52,"y":10,"role":"O"},{"x":68,"y":10,"role":"O"}],"paths":[{"type":"skate","points":[[20,13],[20,40],[20,72]],"step":2,"caption":"Glide across: two skates, then one."},{"type":"skate","points":[[36,13],[36,40],[36,72]],"stepWith":2},{"type":"skate","points":[[52,13],[52,40],[52,72]],"stepWith":2},{"type":"skate","points":[[68,13],[68,40],[68,72]],"stepWith":2},{"type":"backward","points":[[84,74],[84,45],[84,16]],"step":3,"caption":"Backward glides on the way back.","stepSide":"right"}],"labels":[{"x":44,"y":3,"text":"pivot","size":2.6}]}},{"name":"Leg stretched out, then backward glides","adds":"Leg stretched out, then backward glides.","diagram":{"scope":"half","side":"left","players":[{"x":30,"y":6,"role":"C"},{"x":20,"y":10,"role":"O"},{"x":36,"y":10,"role":"O"},{"x":52,"y":10,"role":"O"},{"x":68,"y":10,"role":"O"}],"paths":[{"type":"skate","points":[[20,13],[20,40],[20,72]],"step":2,"caption":"Glide across: two skates, then one."},{"type":"skate","points":[[36,13],[36,40],[36,72]],"stepWith":2},{"type":"skate","points":[[52,13],[52,40],[52,72]],"stepWith":2},{"type":"skate","points":[[68,13],[68,40],[68,72]],"stepWith":2},{"type":"backward","points":[[84,74],[84,45],[84,16]],"step":3,"caption":"Backward glides on the way back.","stepSide":"right"}],"labels":[{"x":44,"y":3,"text":"pivot","size":2.6}]}}],"source":{"label":"Hockey Canada U7 Plan 23 · no skill code","url":"https://cdn.hockeycanada.ca/hockey-canada/Hockey-Programs/Coaching/u7-program/downloads/2020/u7-practice-plan-23-e.pdf","note":"We drew a line following the coach around the zone. In the source it is a progression of pivots and glides across the ice, led by the coach."},"diagram":{"scope":"half","side":"left","players":[{"x":30,"y":6,"role":"C"},{"x":20,"y":10,"role":"O"},{"x":36,"y":10,"role":"O"},{"x":52,"y":10,"role":"O"},{"x":68,"y":10,"role":"O"}],"paths":[{"type":"skate","points":[[20,13],[20,40],[20,72]],"step":2,"caption":"Glide across: two skates, then one."},{"type":"skate","points":[[36,13],[36,40],[36,72]],"stepWith":2},{"type":"skate","points":[[52,13],[52,40],[52,72]],"stepWith":2},{"type":"skate","points":[[68,13],[68,40],[68,72]],"stepWith":2},{"type":"backward","points":[[84,74],[84,45],[84,16]],"step":3,"caption":"Backward glides on the way back.","stepSide":"right"}],"labels":[{"x":44,"y":3,"text":"pivot","size":2.6}]},"id":"airplanes"}'::jsonb),
  ('british-bulldog', 'in_review', '{"funName":"British Bulldog","plainName":"Skate across without getting tagged","sourceTitle":"British Bulldog","minutes":8,"gear":"None","worksAsStation":false,"description":"Skaters start on one side boards. On the whistle they skate across to the other side. The coaches are bulldogs in the middle and tag anyone they can. Tagged skaters become bulldogs for the next crossing. The last skater tagged wins.","steps":["On the whistle, skate across to the other boards.","The bulldogs tag. Tagged? You’re a bulldog next time."],"cues":["Heads up, find the gap!","Skate all the way to the boards."],"focus":[{"attribute":"Effort & fun","level":2,"why":"Racing past the bulldogs."},{"attribute":"Skating","level":1,"why":"Fast starts and quick changes of direction."},{"attribute":"Game sense","level":1,"why":"Heads up to find open ice."}],"groupModel":"basic","part":"game","effort":"hard","format":"everyone","lessons":[2],"levelName":"","levels":[],"source":{"label":"Hockey Canada U7 Lesson 2 · fun game","url":"https://cdn.hockeycanada.ca/hockey-canada/Hockey-Programs/Coaching/u7-program/downloads/2022/u7-practice-plans-phase-1-e.pdf","note":"Drawn across half ice, top boards to bottom boards."},"diagram":{"scope":"half","side":"left","players":[{"x":20,"y":5,"role":"O"},{"x":38,"y":5,"role":"O"},{"x":56,"y":5,"role":"O"},{"x":30,"y":44,"role":"C"},{"x":54,"y":40,"role":"C"}],"paths":[{"type":"skate","points":[[20,5],[16,40],[22,80]],"stepAt":0.2,"step":1,"caption":"On the whistle, skate across to the other boards."},{"type":"skate","points":[[38,5],[44,42],[40,80]],"stepWith":1},{"type":"skate","points":[[56,5],[66,44],[62,80]],"stepWith":1},{"type":"skate","points":[[30,44],[40,47]],"step":2,"caption":"The bulldogs tag. Tagged? You’re a bulldog next time."}],"cones":[]},"id":"british-bulldog"}'::jsonb),
  ('cops-and-robbers', 'in_review', '{"funName":"Cops and Robbers","plainName":"Tag with a jail break","sourceTitle":"Cops and Robbers","minutes":8,"gear":"None (no sticks)","worksAsStation":false,"description":"Coaches are the cops. Skaters are robbers, scattered around the zone with no sticks. A tagged robber goes to jail at the net. A free robber can break them out by tagging them. The cops try to get everyone in jail before time’s up.","steps":["A cop tags a robber.","Tagged? Skate to jail at the net.","Free robbers tag jailed friends to break them out."],"cues":["Look for the cops!","Jail break!"],"focus":[{"attribute":"Effort & fun","level":2,"why":"Chasing, escaping and rescuing friends."},{"attribute":"Skating","level":1,"why":"Quick starts, stops and turns."},{"attribute":"Game sense","level":1,"why":"Heads up to see the cops and the jail."}],"groupModel":"basic","part":"game","effort":"hard","format":"everyone","lessons":[3],"levelName":"","levels":[],"source":{"label":"Hockey Canada U7 Lesson 3 · fun game (also Phase II Lesson 16)","url":"https://cdn.hockeycanada.ca/hockey-canada/Hockey-Programs/Coaching/u7-program/downloads/2022/u7-practice-plans-phase-1-e.pdf","note":"The source allows the net or the referee’s circle as the jail; on half ice we use the net."},"diagram":{"scope":"half","side":"left","players":[{"x":56,"y":24,"role":"C"},{"x":42,"y":16,"role":"O"},{"x":62,"y":56,"role":"O"},{"x":40,"y":70,"role":"O"},{"x":16,"y":40,"role":"O"}],"paths":[{"type":"skate","points":[[56,24],[45,18]],"step":1,"caption":"A cop tags a robber."},{"type":"skate","points":[[42,16],[28,30],[18,37]],"step":2,"caption":"Tagged? Skate to jail at the net."},{"type":"skate","points":[[40,70],[26,56],[18,44]],"step":3,"caption":"Free robbers tag jailed friends to break them out."}],"labels":[{"x":10,"y":30,"text":"Jail"}],"cones":[]},"id":"cops-and-robbers"}'::jsonb),
  ('dont-wake-the-giant', 'in_review', '{"funName":"Don’t Wake the Giant","plainName":"Sneak in, grab a puck, race back","sourceTitle":"Don’t Wake the Giant","minutes":6,"gear":"A pile of pucks","worksAsStation":true,"description":"The pucks are the giant’s treasure, piled in the middle. A coach is the giant, guarding the pile and falling asleep. Skaters tiptoe in from the boards and each take one puck. When the giant wakes up, everyone races back to the boards. Play until the pile is empty.","steps":["Tiptoe in from the boards and take one puck.","The giant wakes up: race back to the boards!"],"cues":["Quiet feet…","Go, go, go!"],"focus":[{"attribute":"Skating","level":2,"why":"Balance on tiptoes, quick starts and stops."},{"attribute":"Effort & fun","level":2,"why":"Sneaking and racing away from the giant."}],"groupModel":"basic","part":"skill","effort":"medium","format":"everyone","lessons":[1],"levelName":"","levels":[],"source":{"label":"Hockey Canada U7 Lesson 1 · skill station","url":"https://cdn.hockeycanada.ca/hockey-canada/Hockey-Programs/Coaching/u7-program/downloads/2022/u7-practice-plans-phase-1-e.pdf","note":"The source doesn’t say how it ends; we end it when the pile is empty."},"diagram":{"scope":"half","side":"left","players":[{"x":46,"y":36,"role":"C"},{"x":22,"y":80,"role":"O"},{"x":40,"y":80,"role":"O"},{"x":48,"y":48,"role":"O"}],"paths":[{"type":"skate","points":[[22,80],[30,60],[37,46]],"step":1,"caption":"Tiptoe in from the boards and take one puck."},{"type":"skate","points":[[40,80],[40,60],[40,49]],"stepWith":1},{"type":"puck","points":[[48,48],[54,62],[58,78]],"step":2,"caption":"The giant wakes up: race back to the boards!"}],"piles":[{"x":40,"y":44}],"cones":[]},"id":"dont-wake-the-giant"}'::jsonb),
  ('game-garbage-trucks', 'in_review', '{"funName":"Garbage Trucks","plainName":"Two-team puck pick-up race","sourceTitle":"Garbage Man","minutes":8,"gear":"All the pucks","worksAsStation":false,"description":"Two teams, each with a face-off circle as home base (the dump). Pucks (garbage) are scattered around the end zone. On the whistle, skate to a puck, stop, pick it up and bring it home, one at a time. Gloves stay on. The team with the most garbage wins.","steps":["Skate to a puck and stop at it.","Bring it home to your circle, one at a time."],"cues":["Stop at every puck!","Gloves on!"],"focus":[{"attribute":"Effort & fun","level":2,"why":"A team race."},{"attribute":"Skating","level":1,"why":"Lots of quick starts and stops."}],"groupModel":"basic","part":"game","effort":"hard","format":"everyone","lessons":[5,6],"levelName":"","levels":[],"source":{"label":"Hockey Canada U7 Lessons 5, 6 · Garbage Man","url":"https://cdn.hockeycanada.ca/hockey-canada/Hockey-Programs/Coaching/u7-program/downloads/2022/u7-practice-plans-phase-1-e.pdf","note":"The source calls it Garbage Man (Garbage Dump in Phase II)."},"diagram":{"scope":"half","side":"left","players":[{"x":31,"y":20,"role":"O"},{"x":31,"y":64,"role":"O"},{"x":45,"y":30,"role":"O"},{"x":45,"y":55,"role":"O"}],"paths":[{"type":"skate","points":[[45,30],[52,38],[58,42]],"step":1,"caption":"Skate to a puck and stop at it.","end":"stop"},{"type":"skate","points":[[58,44],[44,54],[34,62]],"step":2,"caption":"Bring it home to your circle, one at a time."}],"cones":[],"pucks":[{"x":55,"y":12},{"x":60,"y":42},{"x":50,"y":76},{"x":18,"y":42},{"x":66,"y":26}]},"id":"game-garbage-trucks"}'::jsonb),
  ('game-ice-soccer', 'in_review', '{"funName":"Ice Soccer","plainName":"Cross-ice soccer, no sticks","sourceTitle":"Soccer","minutes":10,"gear":"1 soft ball, 4 pylons","worksAsStation":false,"description":"Cross-ice soccer with no sticks. Two teams kick a soft ball toward two pylon goals at the side boards. Play never stops: after a goal the coach rolls the ball back in. No score kept.","steps":["Kick the ball toward the other team’s pylon goal.","Goal? The coach rolls the ball back in."],"cues":["Little kicks, keep your balance.","Find the open ice."],"focus":[{"attribute":"Game sense","level":2,"why":"Space, teammates and attacking a goal."},{"attribute":"Effort & fun","level":2,"why":"A real game, no sticks needed."}],"groupModel":"basic","part":"game","effort":"hard","format":"everyone","lessons":[3],"levelName":"","levels":[],"source":{"label":"Hockey Canada U7 Lesson 3 · fun game","url":"https://cdn.hockeycanada.ca/hockey-canada/Hockey-Programs/Coaching/u7-program/downloads/2022/u7-practice-plans-phase-1-e.pdf","note":"The source only says “Soccer – cross-ice, no sticks”. The pylon goals, the coach restart and no score are ours."},"diagram":{"scope":"half","side":"left","players":[{"x":30,"y":30,"role":"O"},{"x":45,"y":48,"role":"O"},{"x":38,"y":40,"role":"X"},{"x":52,"y":58,"role":"X"},{"x":70,"y":42,"role":"C"}],"paths":[{"type":"skate","points":[[45,48],[42,60],[40,74]],"step":1,"caption":"Kick the ball toward the other team’s pylon goal."},{"type":"pass","points":[[70,42],[52,42]],"step":2,"caption":"Goal? The coach rolls the ball back in.","fromPlayer":false}],"cones":[{"x":34,"y":5},{"x":46,"y":5},{"x":34,"y":80},{"x":46,"y":80}]},"id":"game-ice-soccer"}'::jsonb),
  ('game-steal-the-treasure', 'in_review', '{"funName":"Steal the Treasure","plainName":"Carry pucks past the pirates","sourceTitle":"Steal the Treasure","minutes":10,"gear":"1 crate, all the pucks","worksAsStation":false,"description":"All the pucks (treasure) sit at one end and a crate (the treasure chest) at the other. Skaters carry one puck at a time to the crate. Coaches are pirates: if they tag you, drop the puck and go get another. Gloves stay on. The game ends when the pile is empty.","steps":["Pick up one puck and carry it to the crate.","Tagged by a pirate? Drop the puck and get another."],"cues":["One puck at a time!","Find the open ice."],"focus":[{"attribute":"Effort & fun","level":2,"why":"Everyone races, dodges and scores."},{"attribute":"Skating","level":1,"why":"Starts, stops and dodging."}],"groupModel":"basic","part":"game","effort":"hard","format":"everyone","lessons":[5],"levelName":"","levels":[],"source":{"label":"Hockey Canada U7 Lesson 5 · fun game","url":"https://cdn.hockeycanada.ca/hockey-canada/Hockey-Programs/Coaching/u7-program/downloads/2022/u7-practice-plans-phase-1-e.pdf","note":"The source doesn’t say how it ends; we end it when the pile is empty. The crate is drawn as a pylon."},"diagram":{"scope":"full","players":[{"x":30,"y":30,"role":"O"},{"x":30,"y":50,"role":"O"},{"x":80,"y":40,"role":"O"},{"x":100,"y":25,"role":"C"},{"x":120,"y":60,"role":"C"}],"paths":[{"type":"skate","points":[[32,30],[80,26],[140,34],[168,41]],"step":1,"caption":"Pick up one puck and carry it to the crate."},{"type":"skate","points":[[100,25],[112,30]],"step":2,"caption":"Tagged by a pirate? Drop the puck and get another."}],"cones":[{"x":170,"y":42}],"piles":[{"x":16,"y":42}],"nets":[]},"id":"game-steal-the-treasure"}'::jsonb),
  ('game-sunday-scrimmage', 'in_review', '{"funName":"Sunday Scrimmage","plainName":"Two cross-ice games, one in each end","sourceTitle":"Sunday scrimmage","minutes":30,"gear":"Barrier pads along both blue lines, 4 small nets, pucks","worksAsStation":false,"description":"Barrier pads go across both blue lines, so each end becomes its own small rink. Play a cross-ice game in each end: two small nets against the side boards, one team on each. The neutral zone stays empty. Change lines often so everyone plays.","steps":["Win the puck and skate it toward the other team''s net.","Shoot when you''re close. Then go get it back!"],"cues":["Keep your feet moving.","Head up, find the net.","Lose it? Go get it back!"],"focus":[{"attribute":"Effort & fun","level":2,"why":"Lots of puck touches, shots and goals in a small space."},{"attribute":"Game sense","level":1,"why":"Real game reads: where the puck is, where the net is, who''s open."}],"groupModel":"basic","part":"game","effort":"hard","format":"everyone","lessons":[],"levelName":"","levels":[],"source":{"label":"Our Sunday practice","url":null,"note":"How our team runs Sunday ice: most of the time is two half-ice games across the ice, with barrier pads along the blue lines."},"diagram":{"scope":"full","stations":{"layout":"ends","labels":["Game 1","Game 2"]},"nets":[{"x":40,"y":7,"facing":"down"},{"x":40,"y":78,"facing":"up"},{"x":160,"y":7,"facing":"down"},{"x":160,"y":78,"facing":"up"}],"players":[{"x":28,"y":50,"role":"O"},{"x":52,"y":58,"role":"O"},{"x":52,"y":24,"role":"X"},{"x":58,"y":36,"role":"X"},{"x":148,"y":34,"role":"O"},{"x":172,"y":28,"role":"O"},{"x":150,"y":50,"role":"X"},{"x":142,"y":58,"role":"X"}],"paths":[{"type":"puck","points":[[30,47],[34,34],[38,20]],"step":1,"caption":"Win the puck and skate it toward the other team''s net."},{"type":"shot","points":[[38,18],[40,10]],"step":2,"caption":"Shoot when you''re close. Then go get it back!"},{"type":"puck","points":[[170,31],[166,44],[162,64]],"stepWith":1},{"type":"shot","points":[[161,67],[160,75]],"stepWith":2}]},"id":"game-sunday-scrimmage"}'::jsonb),
  ('horse-and-buggy', 'in_review', '{"funName":"Horse and Buggy","plainName":"Power strides in pairs","sourceTitle":"Horse and Buggy","minutes":8,"gear":"2 sticks per pair","worksAsStation":true,"description":"Partners start at the boards. The horse holds the blades of two sticks and pulls; the buggy holds the shafts and glides behind. The buggy turns one foot to brake, so the horse has to push hard. Swap jobs for the trip back.","steps":["The horse pulls the buggy across the ice.","Swap jobs and come back."],"cues":["Horse: low and long strides.","Buggy: turn one foot to brake."],"focus":[{"attribute":"Skating","level":2,"why":"Power strides for the horse, balance on one edge for the buggy."},{"attribute":"Effort & fun","level":1,"why":"Racing in pairs."}],"groupModel":"stations","part":"skill","effort":"hard","format":"groups","lessons":[5,6],"levelName":"","levels":[],"stations":[{"station":"A","group":"Eagles","version":"Buggy brakes hard. Race the next pair."},{"station":"B","group":"Bears","version":"Partners, light braking."},{"station":"C","group":"Sharks","version":"A coach is the horse. Sharks just glide and hold on."}],"source":{"label":"Hockey Canada U7 Plan 8 · Phase 1 · skill 1.3.06","url":"https://cdn.hockeycanada.ca/hockey-canada/Hockey-Programs/Coaching/u7-program/downloads/2020/u7-practice-plan-08-e.pdf","note":"We had the buggy riding along. In the source the buggy brakes on purpose, which is what makes the horse work hard."},"diagram":{"scope":"half","side":"left","players":[{"x":14,"y":20,"role":"O"},{"x":9,"y":20,"role":"O"},{"x":14,"y":32,"role":"O"},{"x":9,"y":32,"role":"O"},{"x":14,"y":68,"role":"O"},{"x":9,"y":68,"role":"O"},{"x":86,"y":38,"role":"C"},{"x":86,"y":31,"role":"O"}],"paths":[{"type":"skate","points":[[17,20],[38,20],[58,20]],"step":1,"caption":"The horse pulls the buggy across the ice."},{"type":"skate","points":[[17,32],[38,32],[58,32]],"stepWith":1},{"type":"skate","points":[[17,68],[38,68],[58,68]],"stepWith":1},{"type":"skate","points":[[86,41],[86,58],[86,76]],"stepWith":1},{"type":"skate","points":[[58,77],[38,77],[17,77]],"step":2,"caption":"Swap jobs and come back.","stepSide":"right"}],"stations":{"layout":"halfice","labels":["Race in pairs","Pairs","Coach pulls"],"groups":["Eagles","Bears","Sharks"]}},"id":"horse-and-buggy"}'::jsonb),
  ('hot-potato-partners', 'in_review', '{"funName":"Hot Potato Partners","plainName":"Passing on the move","sourceTitle":"Pairs Passing on the Move","minutes":8,"gear":"1 puck per pair","worksAsStation":true,"description":"Partners skate side by side around the zone, passing back and forth as they go. Make sure everyone gets passes on the forehand and the backhand.","steps":["Skate side by side around the zone.","Pass back and forth as you go."],"cues":["Stick on the ice: give a target.","Pass to where they’re going."],"focus":[{"attribute":"Passing","level":2,"why":"Passing and receiving while moving."},{"attribute":"Skating","level":1,"why":"Skating with a partner."},{"attribute":"Puck control","level":1,"why":"Settling a moving puck."}],"groupModel":"basic","part":"skill","effort":"medium","format":"groups","lessons":[],"levelName":"Stand still and pass with a coach","levels":[{"name":"Skate slowly, pass on the forehand","adds":"Skate slowly, pass on the forehand.","diagram":{"scope":"half","side":"left","players":[{"x":22,"y":22,"role":"O"},{"x":22,"y":34,"role":"O"},{"x":60,"y":58,"role":"O"},{"x":60,"y":70,"role":"O"}],"paths":[{"type":"skate","points":[[24,22],[45,20],[64,24],[74,38]],"step":1,"caption":"Skate side by side around the zone."},{"type":"skate","points":[[24,34],[45,34],[60,38],[66,48]],"stepWith":1},{"type":"pass","points":[[40,21],[50,34]],"step":2,"caption":"Pass back and forth as you go.","fromPlayer":false,"stepSide":"right"},{"type":"skate","points":[[58,58],[38,60],[22,52]]},{"type":"skate","points":[[58,70],[36,72],[18,64]]},{"type":"pass","points":[[42,72],[32,60]],"fromPlayer":false}]}},{"name":"Full speed, backhand passes too","adds":"Full speed, backhand passes too.","diagram":{"scope":"half","side":"left","players":[{"x":22,"y":22,"role":"O"},{"x":22,"y":34,"role":"O"},{"x":60,"y":58,"role":"O"},{"x":60,"y":70,"role":"O"}],"paths":[{"type":"skate","points":[[24,22],[45,20],[64,24],[74,38]],"step":1,"caption":"Skate side by side around the zone."},{"type":"skate","points":[[24,34],[45,34],[60,38],[66,48]],"stepWith":1},{"type":"pass","points":[[40,21],[50,34]],"step":2,"caption":"Pass back and forth as you go.","fromPlayer":false,"stepSide":"right"},{"type":"skate","points":[[58,58],[38,60],[22,52]]},{"type":"skate","points":[[58,70],[36,72],[18,64]]},{"type":"pass","points":[[42,72],[32,60]],"fromPlayer":false}]}}],"source":{"label":"Hockey Canada U7 Plans 23, 30 · skills 2.4.01–2.4.02","url":"https://cdn.hockeycanada.ca/hockey-canada/Hockey-Programs/Coaching/u7-program/downloads/2020/u7-practice-plan-23-e.pdf","note":"We drew partners standing still. In the source the pairs skate around the zone and pass on the move, forehand and backhand."},"diagram":{"scope":"half","side":"left","players":[{"x":22,"y":22,"role":"O"},{"x":22,"y":34,"role":"O"},{"x":60,"y":58,"role":"O"},{"x":60,"y":70,"role":"O"}],"paths":[{"type":"skate","points":[[24,22],[45,20],[64,24],[74,38]],"step":1,"caption":"Skate side by side around the zone."},{"type":"skate","points":[[24,34],[45,34],[60,38],[66,48]],"stepWith":1},{"type":"pass","points":[[40,21],[50,34]],"step":2,"caption":"Pass back and forth as you go.","fromPlayer":false,"stepSide":"right"},{"type":"skate","points":[[58,58],[38,60],[22,52]]},{"type":"skate","points":[[58,70],[36,72],[18,64]]},{"type":"pass","points":[[42,72],[32,60]],"fromPlayer":false}]},"id":"hot-potato-partners"}'::jsonb),
  ('inside-out', 'in_review', '{"funName":"Inside Out","plainName":"Stickhandle with eyes up","sourceTitle":"Inside Out","minutes":6,"gear":"1 puck each","worksAsStation":true,"description":"Everyone stickhandles anywhere inside the blue line. When the coach calls “Inside!”, get into one of the face-off circles. On “Out!”, go anywhere except the circles. Move quickly and look up often so you don’t bump into anyone.","steps":["Stickhandle anywhere inside the blue line.","“Inside!” Get into a circle.","“Out!” Get out of the circles."],"cues":["Eyes up, find space.","Little taps, keep it close."],"focus":[{"attribute":"Puck control","level":2,"why":"Stickhandling in traffic."},{"attribute":"Game sense","level":1,"why":"Heads up to find open ice."}],"groupModel":"basic","part":"skill","effort":"medium","format":"everyone","lessons":[9],"levelName":"","levels":[],"source":{"label":"Hockey Canada U7 Phase II Lesson 9 · skill station","url":"https://cdn.hockeycanada.ca/hockey-canada/Hockey-Programs/Coaching/u7-program/downloads/2022/u7-practice-plans-phase-2-e.pdf"},"diagram":{"scope":"half","side":"left","players":[{"x":58,"y":14,"role":"O"},{"x":62,"y":42,"role":"O"},{"x":50,"y":72,"role":"O"},{"x":24,"y":56,"role":"O"},{"x":70,"y":42,"role":"C"}],"paths":[{"type":"puck","points":[[62,42],[52,50],[56,56]],"step":1,"caption":"Stickhandle anywhere inside the blue line."},{"type":"puck","points":[[58,14],[44,18],[36,21]],"step":2,"caption":"“Inside!” Get into a circle."},{"type":"puck","points":[[50,72],[40,68],[34,65]],"stepWith":2},{"type":"puck","points":[[24,56],[36,46],[48,38]],"step":3,"caption":"“Out!” Get out of the circles."}],"cones":[]},"id":"inside-out"}'::jsonb),
  ('keep-away-circle', 'in_review', '{"funName":"Keep Away","plainName":"Pass through the circle, small-group keep away","sourceTitle":"Pass Through The Circle Game","minutes":8,"gear":"Pucks, 4 pylons","worksAsStation":true,"description":"Each group plays keep away around a circle. The passing team scores a point every time they pass through the circle to a teammate. The defenders try to win the puck and knock it out of the area. Every 30 seconds, swap in new defenders.","steps":["Pass through the circle to a teammate to score.","Defenders try to knock the puck out of the area."],"cues":["Heads up, find your open teammate.","No puck? Skate to open ice.","Defenders: stick on the ice."],"focus":[{"attribute":"Game sense","level":2,"why":"Open ice, support and passing lanes."},{"attribute":"Passing","level":1,"why":"Short passes with a defender in the way."},{"attribute":"Effort & fun","level":1,"why":"A game with lots of touches."}],"groupModel":"stations","part":"skill","effort":"medium","format":"groups","lessons":[],"levelName":"","levels":[],"stations":[{"station":"A","group":"Eagles","version":"4 on 2 around a face-off circle."},{"station":"B","group":"Bears","version":"3 on 1 around a face-off circle."},{"station":"C","group":"Sharks","version":"3 on 1 around a pylon square, with a coach defending, stick flipped."}],"source":{"label":"IceHockeySystems · Pass Through The Circle Game","url":"https://www.icehockeysystems.com/hockey-drills/pass-through-circle-game","note":"The source is 4 forwards against 2 defence with a 2-point rule for skating the puck out. We kept one point per pass, swap defenders every 30 seconds, and made it easier for younger groups: 3 on 1, then a coach defending with the stick flipped. Station C has no circle, so four pylons make one."},"diagram":{"scope":"half","side":"left","players":[{"x":12,"y":9,"role":"O"},{"x":50,"y":8,"role":"O"},{"x":52,"y":33,"role":"O"},{"x":11,"y":32,"role":"O"},{"x":22,"y":26,"role":"X"},{"x":40,"y":13,"role":"X"},{"x":12,"y":60,"role":"O"},{"x":50,"y":60,"role":"O"},{"x":31,"y":83,"role":"O"},{"x":30,"y":73,"role":"X"},{"x":79,"y":36,"role":"O"},{"x":96,"y":38,"role":"O"},{"x":93,"y":68,"role":"O"},{"x":90,"y":48,"role":"C"}],"paths":[{"type":"pass","points":[[14,11],[50,31]],"step":1,"caption":"Pass through the circle to a teammate to score."},{"type":"pass","points":[[14,62],[48,61]],"stepWith":1},{"type":"pass","points":[[80,38],[92,66]],"stepWith":1},{"type":"skate","points":[[40,15],[45,22],[49,28]],"step":2,"caption":"Defenders try to knock the puck out of the area."},{"type":"skate","points":[[31,71],[40,66],[46,63]],"stepWith":2}],"cones":[{"x":81,"y":44},{"x":93,"y":44},{"x":81,"y":56},{"x":93,"y":56}],"stations":{"layout":"halfice","labels":["4 on 2","3 on 1","3 on coach"],"groups":["Eagles","Bears","Sharks"]},"pucks":[{"x":14,"y":11},{"x":14,"y":62},{"x":81,"y":38}]},"id":"keep-away-circle"}'::jsonb),
  ('knock-the-tower', 'in_review', '{"funName":"Knock the Tower","plainName":"Hit-the-pylon scrimmage","sourceTitle":"Hit the Pylon Scrimmage","minutes":10,"gear":"1 cone, pinnies, pucks","worksAsStation":true,"description":"Small teams play across the ice. No nets, no goalies: one cone in the middle, and you score by hitting it with the puck. After a goal, give the puck to a coach, who sends it back in. Play never stops.","steps":["Score by hitting the cone.","Goal? Puck to the coach, who sends it back in."],"cues":["Find open ice!","Everyone back when they have it."],"focus":[{"attribute":"Game sense","level":2,"why":"Open ice, support, defending the cone."},{"attribute":"Effort & fun","level":2,"why":"A real game that never stops."},{"attribute":"Shooting","level":1,"why":"Hitting a small target."},{"attribute":"Puck control","level":1,"why":"Lots of touches in traffic."}],"groupModel":"stations","part":"game","effort":"hard","format":"groups","lessons":[4,6],"levelName":"","levels":[],"stations":[{"station":"A","group":"Eagles","version":"3 on 3 with a second puck when one team hogs it."},{"station":"B","group":"Bears","version":"3 on 3."},{"station":"C","group":"Sharks","version":"2 on 2 with a coach helping both teams."}],"source":{"label":"Hockey Canada U7 Plans 15, 23 · no skill code","url":"https://cdn.hockeycanada.ca/hockey-canada/Hockey-Programs/Coaching/u7-program/downloads/2020/u7-practice-plan-15-e.pdf","note":"We drew mini nets. In the source there are no nets or goalies: one pylon in the middle, and you score by hitting it."},"diagram":{"scope":"half","side":"left","players":[{"x":20,"y":18,"role":"O"},{"x":24,"y":34,"role":"O"},{"x":48,"y":16,"role":"O"},{"x":52,"y":32,"role":"X"},{"x":30,"y":16,"role":"X"},{"x":16,"y":28,"role":"X"},{"x":20,"y":58,"role":"O"},{"x":26,"y":74,"role":"O"},{"x":48,"y":58,"role":"O"},{"x":50,"y":72,"role":"X"},{"x":40,"y":76,"role":"X"},{"x":16,"y":68,"role":"X"},{"x":58,"y":78,"role":"C"},{"x":82,"y":38,"role":"O"},{"x":92,"y":66,"role":"O"},{"x":82,"y":66,"role":"X"},{"x":92,"y":40,"role":"X"},{"x":93,"y":52,"role":"C"}],"paths":[{"type":"puck","points":[[26,58],[30,62],[33,65]],"step":1,"caption":"Score by hitting the cone."},{"type":"shot","points":[[33,65],[35,66]],"fromPlayer":false,"stepWith":1},{"type":"puck","points":[[24,34],[29,30],[33,27.5]],"stepWith":1},{"type":"puck","points":[[48,16],[44,22]],"stepWith":1},{"type":"pass","points":[[56,76],[48,70]],"step":2,"caption":"Goal? Puck to the coach, who sends it back in.","fromPlayer":false,"stepSide":"right"}],"cones":[{"x":36,"y":26},{"x":36,"y":66},{"x":87,"y":50}],"stations":{"layout":"halfice","labels":["3 on 3, two pucks","3 on 3","2 on 2 + coach"],"groups":["Eagles","Bears","Sharks"]}},"id":"knock-the-tower"}'::jsonb),
  ('obstacle-course', 'in_review', '{"funName":"Ninja Course","plainName":"Step over, spread out, slide under","sourceTitle":"Obstacle Course","minutes":8,"gear":"4 sticks, 5 pylons","worksAsStation":true,"description":"Lay sticks and pylons in a line. Skaters step over the first stick, spread their skates over the second, step over the third, then slide on their stomach under the stick across two pylons: hands out, head up. Come back weaving through the pylons. Start the next skater when the one ahead reaches the second stick.","steps":["Step over, spread out, step over, then slide under the stick.","Get up and weave back through the pylons."],"cues":["Hands out, head up!","Little steps over the sticks."],"focus":[{"attribute":"Skating","level":2,"why":"Balance, falling safely and getting up."},{"attribute":"Effort & fun","level":1,"why":"An obstacle course feels like a playground."}],"groupModel":"basic","part":"skill","effort":"medium","format":"line","lessons":[3,8],"levelName":"Over, under and weave","levels":[{"name":"Add side steps","adds":"After the slide, side-step toward the goal line and back out, always facing the same way, then weave home.","diagram":{"scope":"half","side":"left","players":[{"x":70,"y":14,"role":"O"},{"x":70,"y":24,"role":"O"}],"paths":[{"type":"skate","points":[[70,14],[46,14],[22,14],[12,18]],"stepAt":0.3,"step":1,"caption":"Step over, spread out, step over, then slide under the stick."},{"type":"skate","points":[[14,22],[12,30],[20,34]],"step":2,"caption":"Side-step toward the goal line and back out."},{"type":"skate","points":[[18,38],[28,46],[34,38],[40,46],[46,38],[52,46],[60,40],[68,30]],"step":3,"caption":"Weave back through the pylons."}],"labels":[{"x":60,"y":6,"text":"Over"},{"x":47,"y":6,"text":"Spread"},{"x":34,"y":6,"text":"Over"},{"x":22,"y":5,"text":"Under"}],"cones":[{"x":22,"y":9},{"x":22,"y":19},{"x":34,"y":42},{"x":46,"y":42},{"x":58,"y":42}],"sticks":[{"points":[[60,10],[60,18]]},{"points":[[52,16],[42,16]]},{"points":[[34,10],[34,18]]},{"points":[[22,9],[22,19]]}]}}],"source":{"label":"Hockey Canada U7 Lessons 3, 8 · 1.1.12","url":"https://cdn.hockeycanada.ca/hockey-canada/Hockey-Programs/Coaching/u7-program/downloads/2022/u7-practice-plans-phase-1-e.pdf","note":"The source diagram isn’t in the text; we lay the course along the top boards. Lesson 8 adds side steps, which is Level 2."},"diagram":{"scope":"half","side":"left","players":[{"x":70,"y":14,"role":"O"},{"x":70,"y":24,"role":"O"}],"paths":[{"type":"skate","points":[[70,14],[46,14],[22,14],[12,18]],"stepAt":0.3,"step":1,"caption":"Step over, spread out, step over, then slide under the stick."},{"type":"skate","points":[[14,24],[22,30],[28,39],[34,30],[40,39],[46,30],[52,39],[60,32],[68,26]],"step":2,"caption":"Get up and weave back through the pylons."}],"labels":[{"x":60,"y":6,"text":"Over"},{"x":47,"y":6,"text":"Spread"},{"x":34,"y":6,"text":"Over"},{"x":22,"y":5,"text":"Under"}],"cones":[{"x":22,"y":9},{"x":22,"y":19},{"x":28,"y":34},{"x":40,"y":34},{"x":52,"y":34}],"sticks":[{"points":[[60,10],[60,18]]},{"points":[[52,16],[42,16]]},{"points":[[34,10],[34,18]]},{"points":[[22,9],[22,19]]}]},"id":"obstacle-course"}'::jsonb),
  ('rotation-backwards-day', 'in_review', '{"funName":"Backwards Day","plainName":"Backward skating and stops, three zones","sourceTitle":"Phase II Lesson 11 skill stations","minutes":6,"gear":"4 pylons","worksAsStation":false,"description":"Three short skating stations. Groups move to the next zone on the whistle until everyone has done all three: walking backwards, gliding backwards off the boards, and stopping at each pylon.","steps":["A: walk backwards from the goal line toward the blue line.","B: push off the boards and glide backwards as far as you can.","C: skate to each pylon and stop facing the next one."],"cues":["Toes in, little steps back.","Sit in the chair.","Stop and look at the next pylon."],"focus":[{"attribute":"Skating","level":2,"why":"Backward stance, backward glide and stopping."},{"attribute":"Effort & fun","level":1,"why":"Beat your own glide."}],"groupModel":"rotation","part":"skill","effort":"medium","format":"groups","lessons":[11],"levelName":"","levels":[],"zones":[{"station":"A","name":"Walk backwards","how":"Line up on the goal line facing the end boards, toes turned in. Walk backwards toward the blue line, lifting each skate.","cue":"Toes in, little steps back."},{"station":"B","name":"Backward glides","how":"Face the boards, push off with both hands and glide backwards as far as you can. Try to beat your last glide.","cue":"Sit in the chair."},{"station":"C","name":"Clock stops","how":"Skate to the first pylon and stop facing the next one. The next skater goes once you have stopped.","cue":"Stop and look at the next pylon."}],"source":{"label":"Hockey Canada U7 Phase II Lesson 11 · 1.5.03, 1.3.06","url":"https://cdn.hockeycanada.ca/hockey-canada/Hockey-Programs/Coaching/u7-program/downloads/2022/u7-practice-plans-phase-2-e.pdf","note":"The source runs six stations in two sets. We kept three that fit the half-ice zones; Horse and Buggy and Toilet Bowl Tag are left for other plans."},"diagram":{"scope":"half","side":"left","players":[{"x":14,"y":12,"role":"O"},{"x":14,"y":22,"role":"O"},{"x":14,"y":32,"role":"O"},{"x":26,"y":80,"role":"O"},{"x":42,"y":80,"role":"O"},{"x":58,"y":80,"role":"O"},{"x":87,"y":14,"role":"O"}],"paths":[{"type":"backward","points":[[16,12],[38,12],[58,12]],"step":1,"caption":"A: walk backwards from the goal line toward the blue line."},{"type":"backward","points":[[16,32],[36,32],[52,32]],"stepWith":1},{"type":"backward","points":[[26,78],[26,66],[26,56]],"step":2,"caption":"B: push off the boards and glide backwards as far as you can."},{"type":"backward","points":[[42,78],[42,62],[42,52]],"stepWith":2},{"type":"skate","points":[[87,16],[87,25]],"step":3,"caption":"C: skate to each pylon and stop facing the next one.","end":"stop"},{"type":"skate","points":[[87,31],[87,41]],"end":"stop","stepWith":3}],"cones":[{"x":87,"y":28},{"x":87,"y":44},{"x":87,"y":60},{"x":87,"y":76}],"stations":{"layout":"halfice","labels":["Walk backwards","Backward glides","Clock stops"]}},"id":"rotation-backwards-day"}'::jsonb),
  ('rotation-edges-and-pucks', 'in_review', '{"funName":"Edges and Pucks","plainName":"Outside edges, stickhandling, side steps, three zones","sourceTitle":"Lesson 6 skill stations","minutes":7,"gear":"1 puck each","worksAsStation":false,"description":"Lesson 6 introduces the puckhandling stance, stationary stickhandling and figure 8s on the outside edge. Groups move to the next zone on the whistle.","steps":["A: ride a figure 8 on the outside edges.","B: move the puck side to side and call out the fingers.","C: side-step down the strip and back."],"cues":["Knees bent, chest up.","Eyes up, soft hands.","Step, step, don’t cross."],"focus":[{"attribute":"Skating","level":2,"why":"Outside edges and lateral movement."},{"attribute":"Puck control","level":1,"why":"First stickhandling, eyes up."}],"groupModel":"rotation","part":"skill","effort":"easy","format":"groups","lessons":[6],"levelName":"","levels":[],"zones":[{"station":"A","name":"Outside 8s","how":"Ride the outside edge of your left skate all the way around the circle, then switch to the right skate to finish the 8.","cue":"Knees bent, chest up."},{"station":"B","name":"Finger count","how":"Puck in front, stick heel just off the ice. Roll your wrists to move the puck side to side and call out how many fingers the coach holds up.","cue":"Eyes up, soft hands."},{"station":"C","name":"Side steps","how":"Ready stance, side-step down the strip and back without crossing your feet. One step, then two, then three each way.","cue":"Step, step, don’t cross."}],"source":{"label":"Hockey Canada U7 Lesson 6 · 1.2.02, 2.1.01, 1.1.11","url":"https://cdn.hockeycanada.ca/hockey-canada/Hockey-Programs/Coaching/u7-program/downloads/2022/u7-practice-plans-phase-1-e.pdf","note":"Lesson 6 also lists inside-edge figure 8s, Horse and Buggy and the stop; those are in Side Step Simon and Horse and Buggy."},"diagram":{"scope":"half","side":"left","players":[{"x":56,"y":6,"role":"O"},{"x":16,"y":56,"role":"O"},{"x":30,"y":56,"role":"O"},{"x":44,"y":56,"role":"O"},{"x":23,"y":72,"role":"O"},{"x":37,"y":72,"role":"O"},{"x":62,"y":64,"role":"C"},{"x":87,"y":17,"role":"O"}],"paths":[{"type":"skate","points":[[31,36.5],[39,34.4],[44.9,28.5],[47,20.5],[44.9,12.5],[39,6.6],[31,4.5],[23,6.6],[17.1,12.5],[15,20.5],[17.1,28.5],[23,34.4],[31,36.5]],"step":1,"caption":"A: ride a figure 8 on the outside edges."},{"type":"puck","points":[[16,59],[20,61],[16,63],[20,65]],"step":2,"caption":"B: move the puck side to side and call out the fingers."},{"type":"skate","points":[[87,20],[85,40],[87,72]],"step":3,"caption":"C: side-step down the strip and back."}],"cones":[],"stations":{"layout":"halfice","labels":["Outside 8s","Finger count","Side steps"]},"pucks":[{"x":19,"y":59},{"x":33,"y":59},{"x":47,"y":59},{"x":26,"y":75},{"x":40,"y":75}]},"id":"rotation-edges-and-pucks"}'::jsonb),
  ('rotation-first-shots', 'in_review', '{"funName":"First Shots","plainName":"Forehand shot, outside edges, skating with the puck","sourceTitle":"Lesson 8 skill stations","minutes":6,"gear":"1 puck each","worksAsStation":false,"description":"One shooting zone, one edges zone and one puck zone. Groups move to the next zone on the whistle.","steps":["Hit the spot: Sweep the puck at a spot on the boards from three or four metres out.","Outside-edge circles: Glide around the circle on the outside edge of your left skate.","Carry the puck: Stickhandle anywhere in the strip, every direction, keeping the puck close."],"cues":["Sweep it, point at the spot.","Bend, lean, chest up.","Little taps, eyes up."],"focus":[{"attribute":"Shooting","level":2,"why":"The first forehand sweep shot."},{"attribute":"Puck control","level":1,"why":"Skating with the puck."},{"attribute":"Skating","level":1,"why":"Outside-edge control."}],"groupModel":"rotation","part":"skill","effort":"medium","format":"groups","lessons":[7,8],"levelName":"","levels":[],"zones":[{"station":"A","name":"Hit the spot","how":"Sweep the puck at a spot on the boards from three or four metres out. Pull it back, sweep it through and point your stick at the spot. Try it without a puck first.","cue":"Sweep it, point at the spot."},{"station":"B","name":"Outside-edge circles","how":"Glide around the circle on the outside edge of your left skate. Next time round, the right skate. Bend your knees and keep your chest up.","cue":"Bend, lean, chest up."},{"station":"C","name":"Carry the puck","how":"Stickhandle anywhere in the strip, every direction, keeping the puck close. Coaches skate around and help.","cue":"Little taps, eyes up."}],"source":{"label":"Hockey Canada U7 Lessons 7, 8 · 3.1.01, 1.2.02, 2.2.01","url":"https://cdn.hockeycanada.ca/hockey-canada/Hockey-Programs/Coaching/u7-program/downloads/2022/u7-practice-plans-phase-1-e.pdf","note":"Lesson 8 runs six stations. We kept the sweep shot, outside-edge figure 8s and skating with the puck. The source draws figure 8s across two circles; on half ice zone B uses one circle per pass."},"diagram":{"scope":"half","side":"left","players":[{"x":46,"y":30,"role":"O"},{"x":58,"y":30,"role":"O"},{"x":70,"y":30,"role":"O"},{"x":48,"y":64,"role":"O"},{"x":84,"y":24,"role":"O"},{"x":92,"y":54,"role":"O"},{"x":22,"y":30,"role":"C"}],"paths":[{"type":"shot","points":[[46,30],[46,15]],"step":1,"stepSide":"right","caption":"Hit the spot: Sweep the puck at a spot on the boards from three or four metres out.","stepLabel":"A"},{"type":"shot","points":[[58,30],[58,15]],"stepWith":1},{"type":"shot","points":[[70,30],[70,15]],"stepWith":1},{"type":"skate","points":[[48,64],[40,52],[28,50],[18,58],[18,70],[28,79],[40,77],[46,68]],"step":2,"caption":"Outside-edge circles: Glide around the circle on the outside edge of your left skate.","stepLabel":"B"},{"type":"puck","points":[[84,24],[90,32],[84,42],[90,48]],"step":3,"stepSide":"right","caption":"Carry the puck: Stickhandle anywhere in the strip, every direction, keeping the puck close.","stepLabel":"C"},{"type":"puck","points":[[92,54],[86,66],[92,76]],"stepWith":3}],"stations":{"layout":"halfice","labels":["Hit the spot","Outside-edge circles","Carry the puck"]},"cones":[{"x":46,"y":12},{"x":58,"y":12},{"x":70,"y":12}]},"id":"rotation-first-shots"}'::jsonb),
  ('rotation-first-steps', 'in_review', '{"funName":"First Steps","plainName":"Getting up, C-cuts and glides, three zones","sourceTitle":"Phase I Lesson 2 skill stations","minutes":6,"gear":"None","worksAsStation":false,"description":"Three first-skating stations for early in the season. Groups move to the next zone on the whistle: getting up off the ice, C-cut pushes, and two-foot then one-foot glides.","steps":["A: get up into ready stance, then skate to the blue line.","B: glide on one foot and push C-cuts with the other.","C: a few strides, then glide on two feet, then one."],"cues":["Knees, hands, up!","Push a C, bring it home.","Freeze like a statue."],"focus":[{"attribute":"Skating","level":2,"why":"Getting up, stance, push and glide."},{"attribute":"Effort & fun","level":1,"why":"Falling and getting up is a game."}],"groupModel":"rotation","part":"skill","effort":"easy","format":"groups","lessons":[2],"levelName":"","levels":[],"zones":[{"station":"A","name":"Get up!","how":"Lie on your back. On the whistle, roll over, get to your knees and stand up in ready stance. Then a few strides, drop to your knees, up again, skate to the blue line.","cue":"Knees, hands, up!"},{"station":"B","name":"C-cuts","how":"Glide on one foot and push C shapes with the other, three or four times. Then switch feet.","cue":"Push a C, bring it home."},{"station":"C","name":"Glide statues","how":"A few strides, then glide on two feet in ready stance like a statue. Then try one foot.","cue":"Freeze like a statue."}],"source":{"label":"Hockey Canada U7 Phase I Lesson 2 · 1.1.02, 1.4.01, 1.1.06–1.1.07","url":"https://cdn.hockeycanada.ca/hockey-canada/Hockey-Programs/Coaching/u7-program/downloads/2020/u7-practice-plan-02-e.pdf","note":"The source offers four, two or six stations. We kept three that fit the half-ice zones; Fall Down, Simon Says and T-push are left for other plans."},"diagram":{"scope":"half","side":"left","players":[{"x":22,"y":18,"role":"O"},{"x":34,"y":18,"role":"O"},{"x":46,"y":18,"role":"O"},{"x":14,"y":60,"role":"O"},{"x":14,"y":72,"role":"O"},{"x":84,"y":16,"role":"O"},{"x":92,"y":16,"role":"O"}],"paths":[{"type":"skate","points":[[22,21],[40,28],[60,30]],"step":1,"caption":"A: get up into ready stance, then skate to the blue line."},{"type":"skate","points":[[16,60],[40,60],[64,60]],"step":2,"caption":"B: glide on one foot and push C-cuts with the other."},{"type":"skate","points":[[16,72],[40,72],[64,72]],"stepWith":2},{"type":"skate","points":[[84,18],[84,46],[84,74]],"step":3,"caption":"C: a few strides, then glide on two feet, then one."}],"cones":[],"stations":{"layout":"halfice","labels":["Get up!","C-cuts","Glide statues"]}},"id":"rotation-first-steps"}'::jsonb),
  ('rotation-green-light', 'in_review', '{"funName":"Green Light","plainName":"Stops, glides and C-cuts, three zones","sourceTitle":"Lesson 4 skill stations","minutes":7,"gear":"None","worksAsStation":false,"description":"A review day from Lesson 4. Groups move to the next zone on the whistle: the one o’clock–eleven o’clock stop as a stop-light game, arm-pump glides, and alternating C-cuts.","steps":["A: skate on green, glide on yellow, stop on red.","B: pump your arms, then glide as far as you can.","C: push alternating C-cuts down the strip."],"cues":["Green go, yellow glide, red stop!","Pump your arms, glide like a rocket.","Push out, bring it home."],"focus":[{"attribute":"Skating","level":2,"why":"Stance, edges, push and stop."}],"groupModel":"rotation","part":"skill","effort":"medium","format":"groups","lessons":[4],"levelName":"","levels":[],"zones":[{"station":"A","name":"Stop lights","how":"Line up on the goal line. Green: skate. Yellow: glide. Red: stop on one skate, the turned foot pushing snow. Cross the zone with several stops, then come back stopping on the other foot.","cue":"Green go, yellow glide, red stop!"},{"station":"B","name":"Rocket glides","how":"Line up on the goal line. Pump your arms to get going, then glide as far as you can on two skates.","cue":"Pump your arms, glide like a rocket."},{"station":"C","name":"C-cut zigzag","how":"Push C shapes with one foot, then the other, bringing each foot back under you before the next push.","cue":"Push out, bring it home."}],"source":{"label":"Hockey Canada U7 Lesson 4 · 1.3.06, 1.1.05, 1.4.02","url":"https://cdn.hockeycanada.ca/hockey-canada/Hockey-Programs/Coaching/u7-program/downloads/2022/u7-practice-plans-phase-1-e.pdf","note":"Lesson 4 introduces nothing new: it reviews Lesson 3. We kept the stops, arm-pump glides and alternating C-cuts; striding, glide turns and edge control are in Race Cars."},"diagram":{"scope":"half","side":"left","players":[{"x":12,"y":16,"role":"O"},{"x":12,"y":28,"role":"O"},{"x":12,"y":40,"role":"O"},{"x":12,"y":54,"role":"O"},{"x":12,"y":66,"role":"O"},{"x":12,"y":78,"role":"O"},{"x":87,"y":17,"role":"O"},{"x":94,"y":17,"role":"O"}],"paths":[{"type":"skate","points":[[14,16],[34,16]],"step":1,"caption":"A: skate on green, glide on yellow, stop on red.","end":"stop"},{"type":"skate","points":[[38,16],[60,16]],"end":"stop","stepWith":1},{"type":"skate","points":[[14,60],[38,60],[64,60]],"step":2,"caption":"B: pump your arms, then glide as far as you can."},{"type":"skate","points":[[87,20],[92,26],[84,40],[92,54],[86,70]],"step":3,"caption":"C: push alternating C-cuts down the strip."}],"cones":[],"stations":{"layout":"halfice","labels":["Stop lights","Rocket glides","C-cut zigzag"]}},"id":"rotation-green-light"}'::jsonb),
  ('rotation-puck-party', 'in_review', '{"funName":"Puck Party","plainName":"Puck control and gliding, three zones","sourceTitle":"Phase II Lesson 9 skill stations","minutes":6,"gear":"1 puck each","worksAsStation":false,"description":"Two puck stations and one skating station. Groups move to the next zone on the whistle: puck handling with eyes up, pushing the puck ahead while skating, and deep knee-bend glides.","steps":["A: move the puck side to side and call out the coach’s fingers.","B: push the puck ahead and chase it across the zone.","C: glide on one foot, bend low, hold it, stand tall."],"cues":["Eyes up, soft hands.","Push it, chase it.","Sit low, hold it, stand tall."],"focus":[{"attribute":"Puck control","level":2,"why":"Stickhandling with eyes up and skating with the puck."},{"attribute":"Skating","level":1,"why":"One-foot glide with a deep knee bend."}],"groupModel":"rotation","part":"skill","effort":"easy","format":"groups","lessons":[9],"levelName":"","levels":[],"zones":[{"station":"A","name":"Finger count","how":"Stand spread out with a puck. Move it side to side, narrow then wide, and call out how many fingers the coach holds up.","cue":"Eyes up, soft hands."},{"station":"B","name":"Push and chase","how":"Start at the boards. Push the puck a little ahead, skate to it and push again, all the way across. Go in waves.","cue":"Push it, chase it."},{"station":"C","name":"Knee-bend glides","how":"A few strides, then glide on one foot. Bend the knee deep, hold it for two seconds, stand up. Switch feet.","cue":"Sit low, hold it, stand tall."}],"source":{"label":"Hockey Canada U7 Phase II Lesson 9 · 2.1.02–2.1.04, 1.1.09","url":"https://cdn.hockeycanada.ca/hockey-canada/Hockey-Programs/Coaching/u7-program/downloads/2022/u7-practice-plans-phase-2-e.pdf","note":"The source runs six stations in two sets. We kept three that fit the half-ice zones; the shooting stations and Inside Out are left for other plans."},"diagram":{"scope":"half","side":"left","players":[{"x":18,"y":14,"role":"O"},{"x":32,"y":14,"role":"O"},{"x":46,"y":14,"role":"O"},{"x":25,"y":28,"role":"O"},{"x":39,"y":28,"role":"O"},{"x":62,"y":21,"role":"C"},{"x":10,"y":56,"role":"O"},{"x":10,"y":68,"role":"O"},{"x":10,"y":78,"role":"O"},{"x":82,"y":16,"role":"O"},{"x":92,"y":16,"role":"O"}],"paths":[{"type":"puck","points":[[18,17],[22,19],[18,21],[22,23]],"step":1,"caption":"A: move the puck side to side and call out the coach’s fingers."},{"type":"puck","points":[[12,56],[38,56],[64,56]],"step":2,"caption":"B: push the puck ahead and chase it across the zone."},{"type":"puck","points":[[12,68],[36,68],[60,68]],"stepWith":2},{"type":"skate","points":[[82,18],[82,40],[82,70]],"step":3,"caption":"C: glide on one foot, bend low, hold it, stand tall."},{"type":"skate","points":[[92,18],[92,36],[92,62]],"stepWith":3}],"cones":[],"stations":{"layout":"halfice","labels":["Finger count","Push and chase","Knee-bend glides"]},"pucks":[{"x":21,"y":17},{"x":35,"y":17},{"x":49,"y":17},{"x":28,"y":31},{"x":42,"y":31}]},"id":"rotation-puck-party"}'::jsonb),
  ('rotation-race-cars', 'in_review', '{"funName":"Race Cars","plainName":"Edges, glide turns and striding, three zones","sourceTitle":"Lesson 3 skill stations","minutes":7,"gear":"4 pylons","worksAsStation":false,"description":"Three skating stations from Lesson 3. Groups move to the next zone on the whistle: riding one edge around a circle, glide turns around a pylon race track, and scooter pushes that turn into striding.","steps":["A: ride the circle on one skate.","B: glide around the race track, turning at each pylon.","C: scoot with one foot, then stride with both."],"cues":["Lean on one skate, other foot up.","Both wheels on the track.","Push, stretch, bring it home."],"focus":[{"attribute":"Skating","level":2,"why":"Stance, edges, push and stop."}],"groupModel":"rotation","part":"skill","effort":"medium","format":"groups","lessons":[3],"levelName":"","levels":[],"zones":[{"station":"A","name":"Edge rides","how":"A few strides, then ride around the circle on your left skate, inside edge, without putting the other foot down. Come back on the outside edge, then switch skates.","cue":"Lean on one skate, other foot up."},{"station":"B","name":"Race track","how":"Four pylons make a race track. A few strides, glide on two skates, and turn around each pylon without lifting a skate. Then go the other way.","cue":"Both wheels on the track."},{"station":"C","name":"Scooters","how":"Push with one skate like a scooter, all the way down, then switch feet. Then stride: push, stretch the leg, bring it back under you.","cue":"Push, stretch, bring it home."}],"source":{"label":"Hockey Canada U7 Lesson 3 · 1.3.01, 1.4.12, 1.6.01, 1.1.05","url":"https://cdn.hockeycanada.ca/hockey-canada/Hockey-Programs/Coaching/u7-program/downloads/2022/u7-practice-plans-phase-1-e.pdf","note":"Lesson 3 has six stations in two sets. We kept edge control, glide turns and striding; arm-pump glides, alternating C-cuts and stops come back in Lesson 4."},"diagram":{"scope":"half","side":"left","players":[{"x":56,"y":6,"role":"O"},{"x":62,"y":6,"role":"O"},{"x":26,"y":50,"role":"O"},{"x":34,"y":50,"role":"O"},{"x":87,"y":17,"role":"O"},{"x":94,"y":17,"role":"O"}],"paths":[{"type":"skate","points":[[43.3,10.2],[39,6.6],[33.8,4.7],[28.2,4.7],[23,6.6],[18.7,10.2],[16,15],[15,20.5],[16,26]],"step":1,"caption":"A: ride the circle on one skate."},{"type":"skate","points":[[14,52],[34,51],[54,53],[56,68],[54,81],[34,82],[16,80],[13,66]],"step":2,"caption":"B: glide around the race track, turning at each pylon."},{"type":"skate","points":[[87,20],[87,40],[87,72]],"step":3,"caption":"C: scoot with one foot, then stride with both."}],"cones":[{"x":18,"y":55},{"x":50,"y":55},{"x":50,"y":78},{"x":18,"y":78}],"stations":{"layout":"halfice","labels":["Edge rides","Race track","Scooters"]}},"id":"rotation-race-cars"}'::jsonb),
  ('rotation-reverse-gear', 'in_review', '{"funName":"Reverse Gear","plainName":"Backward C-cuts, stickhandling, backward striding","sourceTitle":"Phase II Lesson 12 skill stations","minutes":6,"gear":"1 puck each","worksAsStation":false,"description":"Two backward-skating zones and a stickhandling zone. Groups move to the next zone on the whistle.","steps":["Boards C-cuts: Hold the boards and push backward C-cuts out with one skate, then the other.","Side, front, side: Stickhandle on your forehand side, then in front, then on your backhand side.","Backward stride: Skate backwards across the strip with C-cuts, one foot there and the other foot back."],"cues":["Toe in, push, bring it home.","Side, front, side.","Sit low, push to the side."],"focus":[{"attribute":"Skating","level":2,"why":"Backward C-cuts and backward striding."},{"attribute":"Puck control","level":1,"why":"Stickhandling side, front, side."}],"groupModel":"rotation","part":"skill","effort":"medium","format":"groups","lessons":[12],"levelName":"","levels":[],"zones":[{"station":"A","name":"Boards C-cuts","how":"Hold the boards and push backward C-cuts out with one skate, then the other. Hands shoulder-width apart; bring each skate home.","cue":"Toe in, push, bring it home."},{"station":"B","name":"Side, front, side","how":"Stickhandle on your forehand side, then in front, then on your backhand side. Look up at the coach when you can.","cue":"Side, front, side."},{"station":"C","name":"Backward stride","how":"Skate backwards across the strip with C-cuts, one foot there and the other foot back. Start facing the boards. Then alternate feet and glide.","cue":"Sit low, push to the side."}],"source":{"label":"Hockey Canada U7 Phase II Lesson 12 · 1.5.01–1.5.02, 2.1.05","url":"https://cdn.hockeycanada.ca/hockey-canada/Hockey-Programs/Coaching/u7-program/downloads/2022/u7-practice-plans-phase-2-e.pdf","note":"The source runs six stations. We kept C-cuts at the boards, side-front-side stickhandling and backward striding; Stick Checks, A Bug’s Life and C-cuts around the circle are left for other plans. Backward striding runs across the neutral strip instead of goal line to blue line."},"diagram":{"scope":"half","side":"left","players":[{"x":48,"y":6,"role":"O"},{"x":59,"y":6,"role":"O"},{"x":70,"y":6,"role":"O"},{"x":26,"y":66,"role":"O"},{"x":46,"y":66,"role":"O"},{"x":62,"y":76,"role":"C"},{"x":83,"y":22,"role":"O"},{"x":93,"y":22,"role":"O"}],"paths":[{"type":"backward","points":[[48,6],[46,20]],"step":1,"stepSide":"right","caption":"Boards C-cuts: Hold the boards and push backward C-cuts out with one skate, then the other.","stepLabel":"A"},{"type":"backward","points":[[59,6],[57,20]],"stepWith":1},{"type":"backward","points":[[70,6],[68,20]],"stepWith":1},{"type":"puck","points":[[20,60],[26,56],[32,60]],"fromPlayer":false,"step":2,"caption":"Side, front, side: Stickhandle on your forehand side, then in front, then on your backhand side.","stepLabel":"B"},{"type":"puck","points":[[40,60],[46,56],[52,60]],"fromPlayer":false,"stepWith":2},{"type":"backward","points":[[83,22],[85,50],[83,78]],"step":3,"caption":"Backward stride: Skate backwards across the strip with C-cuts, one foot there and the other foot back.","stepLabel":"C"},{"type":"backward","points":[[93,22],[93,48],[93,72]],"stepWith":3}],"stations":{"layout":"halfice","labels":["Boards C-cuts","Side, front, side","Backward stride"]},"pucks":[{"x":26,"y":61},{"x":46,"y":61}],"cones":[]},"id":"rotation-reverse-gear"}'::jsonb),
  ('rotation-side-step-simon', 'in_review', '{"funName":"Side Step Simon","plainName":"Figure 8s, side steps and stops, three zones","sourceTitle":"Lesson 5 skill stations","minutes":7,"gear":"4 pylons","worksAsStation":false,"description":"Lesson 5 introduces lateral movement and figure 8s on the inside edge. Groups move to the next zone on the whistle: figure 8s around the circle, side steps with Simon Says, and stops at a line of pylons.","steps":["A: ride a figure 8 on the inside edges.","B: side-step left and right, then play Simon Says.","C: stop at each pylon, facing the next."],"cues":["Knees bent, lean in.","Step, step, don’t cross.","Glide, then stop."],"focus":[{"attribute":"Skating","level":2,"why":"Stance, edges, push and stop."}],"groupModel":"rotation","part":"skill","effort":"medium","format":"groups","lessons":[5],"levelName":"","levels":[],"zones":[{"station":"A","name":"Figure 8s","how":"Ride the inside edge of your right skate all the way around the circle, then switch to the left skate to finish the 8.","cue":"Knees bent, lean in."},{"station":"B","name":"Side Step Simon","how":"Line up on the goal line in ready stance. Side-step one step left and right, then two, then three, without crossing your feet. Then Simon Says: knees, hop, tiptoes, one foot, roll over.","cue":"Step, step, don’t cross."},{"station":"C","name":"Pylon stops","how":"Skate to the first pylon and stop facing the next one. The next skater goes once you have stopped.","cue":"Glide, then stop."}],"source":{"label":"Hockey Canada U7 Lesson 5 · 1.2.01, 1.1.11, 1.3.06","url":"https://cdn.hockeycanada.ca/hockey-canada/Hockey-Programs/Coaching/u7-program/downloads/2022/u7-practice-plans-phase-1-e.pdf","note":"The source draws figure 8s across two circles; on half ice we use one circle per pass. Striding, arm-pump glides and Horse and Buggy are the other Lesson 5 stations."},"diagram":{"scope":"half","side":"left","players":[{"x":56,"y":6,"role":"O"},{"x":12,"y":52,"role":"O"},{"x":12,"y":62,"role":"O"},{"x":12,"y":72,"role":"O"},{"x":12,"y":82,"role":"O"},{"x":40,"y":66,"role":"C"},{"x":87,"y":17,"role":"O"}],"paths":[{"type":"skate","points":[[31,4.5],[39,6.6],[44.9,12.5],[47,20.5],[44.9,28.5],[39,34.4],[31,36.5],[23,34.4],[17.1,28.5],[15,20.5],[17.1,12.5],[23,6.6],[31,4.5]],"step":1,"caption":"A: ride a figure 8 on the inside edges."},{"type":"skate","points":[[16,62],[16,56]],"stepWith":2},{"type":"skate","points":[[16,72],[16,78]],"step":2,"caption":"B: side-step left and right, then play Simon Says."},{"type":"skate","points":[[87,20],[87,25]],"step":3,"caption":"C: stop at each pylon, facing the next.","end":"stop"},{"type":"skate","points":[[87,31],[87,41]],"end":"stop","stepWith":3}],"cones":[{"x":87,"y":28},{"x":87,"y":44},{"x":87,"y":60},{"x":87,"y":76}],"stations":{"layout":"halfice","labels":["Figure 8s","Side Step Simon","Pylon stops"]}},"id":"rotation-side-step-simon"}'::jsonb),
  ('scatter-puck', 'in_review', '{"funName":"Scatter Puck","plainName":"Shoot your pucks to the other side","sourceTitle":"Scatter Puck","minutes":6,"gear":"All the pucks, split evenly","worksAsStation":false,"description":"Two teams, one on each side of a line, with the same number of pucks. On the whistle, shoot pucks over to the other side, then keep gathering and shooting until the next whistle. Nobody crosses the line. The team with fewer pucks on its side wins. Even the pucks up and play again.","steps":["On the whistle, shoot pucks to the other side.","Gather and shoot again until the whistle. Fewest pucks wins."],"cues":["Sweep it, don’t slap it.","Stay on your side!"],"focus":[{"attribute":"Shooting","level":2,"why":"Lots of forehand shots, fast."},{"attribute":"Effort & fun","level":2,"why":"A race against the other team."},{"attribute":"Puck control","level":1,"why":"Gathering loose pucks."}],"groupModel":"basic","part":"game","effort":"hard","format":"everyone","lessons":[9,10],"levelName":"Forehand shots","levels":[{"name":"Backhands only","adds":"Same game, but every shot is a backhand.","diagram":{"scope":"half","side":"left","players":[{"x":24,"y":22,"role":"O"},{"x":46,"y":26,"role":"O"},{"x":64,"y":18,"role":"O"},{"x":30,"y":64,"role":"O"},{"x":52,"y":60,"role":"O"}],"paths":[{"type":"shot","points":[[24,22],[26,56]],"stepSide":"right","step":1,"caption":"On the whistle, shoot pucks to the other side."},{"type":"shot","points":[[52,60],[48,30]],"stepWith":1},{"type":"puck","points":[[64,18],[60,30],[64,36]],"step":2,"caption":"Gather and shoot again until the whistle. Fewest pucks wins."}],"areas":[{"x":14,"y":4,"w":58,"h":35},{"x":14,"y":46,"w":58,"h":35}],"pucks":[{"x":36,"y":14},{"x":58,"y":32},{"x":40,"y":74},{"x":62,"y":72}],"cones":[]}}],"source":{"label":"Hockey Canada U7 Phase II Lessons 9, 10","url":"https://cdn.hockeycanada.ca/hockey-canada/Hockey-Programs/Coaching/u7-program/downloads/2022/u7-practice-plans-phase-2-e.pdf","note":"The source uses a painted centre line. On half ice we split the zone top and bottom; Lesson 10 repeats it with backhands only, which is Level 2."},"diagram":{"scope":"half","side":"left","players":[{"x":24,"y":22,"role":"O"},{"x":46,"y":26,"role":"O"},{"x":64,"y":18,"role":"O"},{"x":30,"y":64,"role":"O"},{"x":52,"y":60,"role":"O"}],"paths":[{"type":"shot","points":[[24,22],[26,56]],"stepSide":"right","step":1,"caption":"On the whistle, shoot pucks to the other side."},{"type":"shot","points":[[52,60],[48,30]],"stepWith":1},{"type":"puck","points":[[64,18],[60,30],[64,36]],"step":2,"caption":"Gather and shoot again until the whistle. Fewest pucks wins."}],"areas":[{"x":14,"y":4,"w":58,"h":35},{"x":14,"y":46,"w":58,"h":35}],"pucks":[{"x":36,"y":14},{"x":58,"y":32},{"x":40,"y":74},{"x":62,"y":72}],"cones":[]},"id":"scatter-puck"}'::jsonb),
  ('ski-racer', 'in_review', '{"funName":"Ski Racer","plainName":"Tight turns through cones","sourceTitle":"Tight Turns","minutes":8,"gear":"5 cones","worksAsStation":true,"description":"Set up a zig-zag of cones from centre ice toward the net. Skate the course and turn tight around every cone. The next skater goes when the one ahead reaches the second cone.","steps":["Turn tight around every cone.","Next skater goes at the second cone."],"cues":["Knees bent, lean into the turn.","Look where you want to go."],"focus":[{"attribute":"Skating","level":2,"why":"Turning on both edges."}],"groupModel":"basic","part":"skill","effort":"hard","format":"line","lessons":[],"levelName":"Skate the course","levels":[{"name":"Pass and shoot at the end","adds":"A coach passes as you come off the last cone. Shoot on the net.","diagram":{"scope":"half","side":"left","players":[{"x":89,"y":42,"role":"O"},{"x":20,"y":72,"role":"C"}],"paths":[{"type":"skate","points":[[89,42],[80,26],[73,32],[68,56],[61,50],[56,26],[49,32],[44,56],[37,50],[32,26],[25,32],[21,42]]},{"type":"pass","points":[[20,69],[21,47]],"fromPlayer":false},{"type":"shot","points":[[21,42],[14,42.5]],"fromPlayer":false}],"cones":[{"x":77,"y":30},{"x":65,"y":52},{"x":53,"y":30},{"x":41,"y":52},{"x":29,"y":30}]}},{"name":"Carry it all the way","adds":"Puck on your stick through every turn, then shoot.","diagram":{"scope":"half","side":"left","players":[{"x":89,"y":42,"role":"O"}],"paths":[{"type":"puck","points":[[89,42],[80,26],[73,32],[68,56],[61,50],[56,26],[49,32],[44,56],[37,50],[32,26],[25,32],[21,42]]},{"type":"shot","points":[[21,42],[14,42.5]],"fromPlayer":false}],"cones":[{"x":77,"y":30},{"x":65,"y":52},{"x":53,"y":30},{"x":41,"y":52},{"x":29,"y":30}]}}],"source":{"label":"Hockey Canada U7 Plans 15, 30 · skill 1.6.02","url":"https://cdn.hockeycanada.ca/hockey-canada/Hockey-Programs/Coaching/u7-program/downloads/2020/u7-practice-plan-15-e.pdf","note":"Right idea. The source adds a zig-zag course and a staggered start, so the line keeps moving."},"diagram":{"scope":"half","side":"left","players":[{"x":89,"y":42,"role":"O"},{"x":92,"y":49,"role":"O"},{"x":95,"y":56,"role":"O"}],"paths":[{"type":"skate","points":[[89,42],[80,26],[73,32],[68,56],[61,50],[56,26],[49,32],[44,56],[37,50],[32,26],[25,32],[21,42]],"step":1,"caption":"Turn tight around every cone."},{"type":"skate","points":[[92,49],[84,36]],"step":2,"caption":"Next skater goes at the second cone.","stepSide":"right"}],"cones":[{"x":77,"y":30},{"x":65,"y":52},{"x":53,"y":30},{"x":41,"y":52},{"x":29,"y":30}]},"id":"ski-racer"}'::jsonb),
  ('snake-in-the-forest', 'in_review', '{"funName":"Snake in the Forest","plainName":"Weave, circle and shoot","sourceTitle":"Weave, Circle and Glide Turn","minutes":8,"gear":"1 puck each, 6 cones","worksAsStation":true,"description":"Start in the corner. Weave up the boards through four cones, skate a full circle around the fifth, glide-turn around the last one near the blue line, then come back down the middle to the net and shoot.","steps":["Weave up the boards, circle the fifth cone.","Glide turn at the last cone.","Come back down the middle and shoot."],"cues":["Soft hands, puck in front.","Peek up between cones."],"focus":[{"attribute":"Puck control","level":2,"why":"Moving puck control through turns."},{"attribute":"Skating","level":1,"why":"Edges and a glide turn."},{"attribute":"Passing","level":1,"why":"Receiving from the coach, and the give-and-go."},{"attribute":"Shooting","level":1,"why":"A shot to finish."}],"groupModel":"basic","part":"skill","effort":"medium","format":"line","lessons":[],"levelName":"Skate it, then a pass","levels":[{"name":"Puck the whole way","adds":"Carry the puck through every cone, the circle and the glide turn, then shoot.","diagram":{"scope":"half","side":"left","players":[{"x":12,"y":74,"role":"O"}],"paths":[{"type":"puck","points":[[12,74],[19,68],[29,60],[39,68],[49,60],[58,66],[62,58],[70,58],[71,69],[62,70],[64,62],[78,56],[88,54],[90,62],[84,66],[74,52],[58,44],[40,42],[26,42]]},{"type":"shot","points":[[26,42],[14,42.5]],"fromPlayer":false}],"cones":[{"x":24,"y":64},{"x":34,"y":64},{"x":44,"y":64},{"x":54,"y":64},{"x":66,"y":64},{"x":84,"y":60}]}},{"name":"Give-and-go at the blue line","adds":"With the puck: pass to the coach as you enter the zone, get it back, shoot.","diagram":{"scope":"half","side":"left","players":[{"x":12,"y":74,"role":"O"},{"x":62,"y":26,"role":"C"}],"paths":[{"type":"puck","points":[[12,74],[19,68],[29,60],[39,68],[49,60],[58,66],[62,58],[70,58],[71,69],[62,70],[64,62],[78,56],[88,54],[90,62],[84,66],[78,56]]},{"type":"pass","points":[[76,54],[64,29]],"fromPlayer":false},{"type":"pass","points":[[60,29],[52,42]],"fromPlayer":false},{"type":"puck","points":[[52,43],[40,42],[26,42]]},{"type":"shot","points":[[26,42],[14,42.5]],"fromPlayer":false}],"cones":[{"x":24,"y":64},{"x":34,"y":64},{"x":44,"y":64},{"x":54,"y":64},{"x":66,"y":64},{"x":84,"y":60}]}}],"source":{"label":"Hockey Canada U7 Plan 15 · skill 2.2.08","url":"https://cdn.hockeycanada.ca/hockey-canada/Hockey-Programs/Coaching/u7-program/downloads/2020/u7-practice-plan-15-e.pdf","note":"We had a plain slalom. The source adds a full circle around the fifth cone and a glide turn at the end. We kept those and changed the finish: out of the corner, up the boards, then back down to the net for a shot."},"diagram":{"scope":"half","side":"left","players":[{"x":12,"y":74,"role":"O"},{"x":8,"y":78,"role":"O"},{"x":42,"y":22,"role":"C"}],"paths":[{"type":"skate","points":[[12,74],[19,68],[29,60],[39,68],[49,60],[58,66],[62,58],[70,58],[71,69],[62,70],[64,62]],"step":1,"caption":"Weave up the boards, circle the fifth cone."},{"type":"skate","points":[[66,60],[78,56],[88,54],[90,62],[84,66]],"step":2,"caption":"Glide turn at the last cone.","stepSide":"right"},{"type":"skate","points":[[82,62],[74,52],[58,44],[40,42],[26,42]],"step":3,"caption":"Come back down the middle and shoot.","stepAt":0.4},{"type":"pass","points":[[42,25],[40,40]],"fromPlayer":false,"stepWith":3},{"type":"shot","points":[[26,42],[14,42.5]],"stepWith":3,"fromPlayer":false}],"cones":[{"x":24,"y":64},{"x":34,"y":64},{"x":44,"y":64},{"x":54,"y":64},{"x":66,"y":64},{"x":84,"y":60}]},"id":"snake-in-the-forest"}'::jsonb),
  ('toilet-bowl-tag', 'in_review', '{"funName":"Toilet Bowl Tag","plainName":"Tag, freeze, and flush to free a friend","sourceTitle":"Toilet Bowl Tag","minutes":8,"gear":"None (no sticks)","worksAsStation":false,"description":"No sticks. Skaters skate around the zone with hands on their knees. Coaches are it. A tagged skater stands still with one arm straight out: the flusher. To free them, another skater skates under the arm, stops, and pushes the arm down. Flush!","steps":["Skate around with hands on your knees.","Tagged? Freeze with one arm out.","Skate under a friend’s arm, stop, and flush to free them."],"cues":["Hands on knees, stay low!","Stop, then flush!"],"focus":[{"attribute":"Effort & fun","level":2,"why":"Tag with a silly rescue."},{"attribute":"Skating","level":1,"why":"Low stance, starts and stops."}],"groupModel":"basic","part":"game","effort":"hard","format":"everyone","lessons":[9,11],"levelName":"","levels":[],"source":{"label":"Hockey Canada U7 Phase II Lesson 9 · fun game (Lesson 11 station)","url":"https://cdn.hockeycanada.ca/hockey-canada/Hockey-Programs/Coaching/u7-program/downloads/2022/u7-practice-plans-phase-2-e.pdf"},"diagram":{"scope":"half","side":"left","players":[{"x":58,"y":22,"role":"C"},{"x":50,"y":14,"role":"O"},{"x":36,"y":52,"role":"O"},{"x":60,"y":66,"role":"O"},{"x":22,"y":28,"role":"O"}],"paths":[{"type":"skate","points":[[22,28],[30,40],[44,38],[56,46]],"step":1,"caption":"Skate around with hands on your knees."},{"type":"skate","points":[[58,22],[52,16]],"step":2,"caption":"Tagged? Freeze with one arm out."},{"type":"skate","points":[[60,66],[46,58],[39,54]],"end":"stop","step":3,"caption":"Skate under a friend’s arm, stop, and flush to free them."}],"labels":[{"x":30,"y":60,"text":"Flusher"}],"cones":[]},"id":"toilet-bowl-tag"}'::jsonb),
  ('tour-bus', 'in_review', '{"funName":"Tour Bus","plainName":"Follow the coach and learn the rink","sourceTitle":"Tour Bus","minutes":6,"gear":"None","worksAsStation":true,"description":"One bus per coach. The coach is the driver and the skaters are passengers who follow close behind. Drive slowly, change direction often, and stop at the face-off dot, the circle, the net, the crease and the lines. Come back to a spot and ask the kids to name it.","steps":["Follow your bus driver, slow and close.","Stop at each spot and shout its name."],"cues":["Stay behind the bus!","What’s this one called?"],"focus":[{"attribute":"Skating","level":2,"why":"Skating in a line, turning and stopping."},{"attribute":"Game sense","level":1,"why":"Learning the names of the rink’s lines and spots."},{"attribute":"Effort & fun","level":1,"why":"A calm, playful first-practice game."}],"groupModel":"basic","part":"game","effort":"easy","format":"groups","lessons":[1],"levelName":"","levels":[],"source":{"label":"Hockey Canada U7 Lesson 1 · fun game","url":"https://cdn.hockeycanada.ca/hockey-canada/Hockey-Programs/Coaching/u7-program/downloads/2022/u7-practice-plans-phase-1-e.pdf","note":"The source tours the whole rink. We draw one bus on half ice; with three coaches, run three buses."},"diagram":{"scope":"half","side":"left","players":[{"x":66,"y":30,"role":"C"},{"x":72,"y":22,"role":"O"},{"x":74,"y":15,"role":"O"},{"x":72,"y":8,"role":"O"}],"paths":[{"type":"skate","points":[[66,30],[44,30],[31,22],[18,34],[16,48],[31,64],[52,66]],"step":1,"caption":"Follow your bus driver, slow and close."}],"labels":[{"x":31,"y":15,"text":"Dot"},{"x":22,"y":42.5,"text":"Crease"},{"x":75,"y":80,"text":"Blue line"}],"cones":[]},"id":"tour-bus"}'::jsonb),
  ('warmup-free-skate-challenges', 'in_review', '{"funName":"Free Skate Challenges","plainName":"Warm-up laps with skating challenges","sourceTitle":"Free Skate","minutes":8,"gear":"None","worksAsStation":false,"description":"Everyone skates laps between the blue lines, going clockwise. The coach calls a challenge every few seconds: fall to your knees and get up, glide on one foot, jump the lines, C-cuts, then speed up.","steps":["Skate laps between the blue lines, going clockwise.","On the call: knees and up, one-foot glide, jump the lines, C-cuts, speed up."],"cues":["Knees, hands, up!","Eyes up, find space."],"focus":[{"attribute":"Skating","level":2,"why":"Lots of laps with balance and edge challenges."},{"attribute":"Effort & fun","level":1,"why":"Fast changes keep everyone moving."}],"groupModel":"basic","part":"warmup","effort":"medium","format":"everyone","lessons":[3,5],"levelName":"","levels":[],"source":{"label":"Hockey Canada U7 Lessons 3, 5 · 1.1.02, 1.1.07, 1.1.04, 1.4.02","url":"https://cdn.hockeycanada.ca/hockey-canada/Hockey-Programs/Coaching/u7-program/downloads/2022/u7-practice-plans-phase-1-e.pdf","note":"The source calls it Free Skate; Lesson 3 uses knees, one-foot glides and jumping the lines, Lesson 5 adds C-cuts."},"diagram":{"scope":"full","players":[{"x":84,"y":14,"role":"O"},{"x":110,"y":12,"role":"O"},{"x":122,"y":40,"role":"O"},{"x":112,"y":72,"role":"O"},{"x":86,"y":70,"role":"O"},{"x":100,"y":42,"role":"C"}],"paths":[{"type":"skate","points":[[84,12],[100,9],[118,12],[123,40],[118,72],[100,76],[82,72],[77,42],[82,16]],"step":1,"caption":"Skate laps between the blue lines, going clockwise."},{"type":"skate","points":[[112,72],[104,74]],"step":2,"caption":"On the call: knees and up, one-foot glide, jump the lines, C-cuts, speed up.","end":"stop"}],"cones":[]},"id":"warmup-free-skate-challenges"}'::jsonb),
  ('warmup-skill-doctor-tag', 'in_review', '{"funName":"Skill Doctor Tag","plainName":"Tag warm-up with skill tasks","sourceTitle":"Tag","minutes":8,"gear":"None","worksAsStation":false,"description":"Coaches are it. A tagged skater goes to the Skill Doctor, a coach at the referee’s circle, who gives a task: fall to your knees and get up, balance on one foot, jump on one foot, or C-cuts. Then back into the game.","steps":["Coaches chase and tag.","Tagged? See the Skill Doctor, do the task, and skate back in."],"cues":["Keep your head up!","Do the task, then go!"],"focus":[{"attribute":"Effort & fun","level":2,"why":"A chasing game everyone plays."},{"attribute":"Skating","level":1,"why":"Agility, balance and quick starts."}],"groupModel":"basic","part":"warmup","effort":"hard","format":"everyone","lessons":[4,6],"levelName":"","levels":[],"source":{"label":"Hockey Canada U7 Lessons 4, 6 · 1.1.02–1.1.04, 1.4.03","url":"https://cdn.hockeycanada.ca/hockey-canada/Hockey-Programs/Coaching/u7-program/downloads/2022/u7-practice-plans-phase-1-e.pdf","note":"The source calls it Tag. The Skill Doctor stands at the referee’s circle."},"diagram":{"scope":"full","players":[{"x":50,"y":20,"role":"O"},{"x":70,"y":60,"role":"O"},{"x":130,"y":24,"role":"O"},{"x":150,"y":58,"role":"O"},{"x":96,"y":30,"role":"O"},{"x":60,"y":40,"role":"C"},{"x":140,"y":40,"role":"C"},{"x":100,"y":79,"role":"C"}],"paths":[{"type":"skate","points":[[60,40],[66,52],[70,58]],"step":1,"caption":"Coaches chase and tag."},{"type":"skate","points":[[72,62],[86,72],[98,77]],"step":2,"caption":"Tagged? See the Skill Doctor, do the task, and skate back in."}],"cones":[]},"id":"warmup-skill-doctor-tag"}'::jsonb)
